--
-- Table structure for table `accounts_profile`
--

DROP TABLE IF EXISTS `accounts_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `accounts_profile` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `first_name` varchar(30) DEFAULT NULL,
  `middle_name` varchar(30) DEFAULT NULL,
  `last_name` varchar(30) DEFAULT NULL,
  `date_birth` date DEFAULT NULL,
  `phone_number` varchar(11) DEFAULT NULL,
  `gender` varchar(10) NOT NULL,
  `marital_status` varchar(16) NOT NULL,
  `Number_children` int(11) NOT NULL,
  `home_address` varchar(200) DEFAULT NULL,
  `religion` varchar(40) NOT NULL,
  `nationality` varchar(40) NOT NULL,
  `role` varchar(30) DEFAULT NULL,
  `image` varchar(100) NOT NULL,
  `last_updated` datetime(6) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `lga_id` bigint(20) DEFAULT NULL,
  `state_id` bigint(20) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `accounts_profile_state_id_a939afe9_fk_accounts_state_id` (`state_id`),
  KEY `accounts_profile_lga_id_5ec59be7_fk_accounts_localgovernment_id` (`lga_id`),
  CONSTRAINT `accounts_profile_lga_id_5ec59be7_fk_accounts_localgovernment_id` FOREIGN KEY (`lga_id`) REFERENCES `accounts_localgovernment` (`id`),
  CONSTRAINT `accounts_profile_state_id_a939afe9_fk_accounts_state_id` FOREIGN KEY (`state_id`) REFERENCES `accounts_state` (`id`),
  CONSTRAINT `accounts_profile_user_id_49a85d32_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

