  CONSTRAINT `accounts_staffpublic_staff2_id_657d43ba_fk_accounts_` FOREIGN KEY (`staff2_id`) REFERENCES `accounts_profile` (`id`),
  CONSTRAINT `accounts_staffpublic_staff_id_45185f56_fk_accounts_` FOREIGN KEY (`staff_id`) REFERENCES `accounts_staffregister` (`id`),
  CONSTRAINT `accounts_staffpublic_submitted_by_id_00513058_fk_auth_user` FOREIGN KEY (`submitted_by_id`) REFERENCES `auth_user` (`id`)
