DROP TABLE IF EXISTS `admission_admitted`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `admission_admitted` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `semester` varchar(20) NOT NULL,
  `admitted_level` varchar(100) NOT NULL,
  `admitted_date` date NOT NULL,
  `admitted_at` datetime(6) NOT NULL,
  `academic_session_id` bigint(20) NOT NULL,
  `admitted_course_id` bigint(20) NOT NULL,
  `applicant_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `applicant_id` (`applicant_id`),
  KEY `admission_admitted_academic_session_id_d1579ad1_fk_academics` (`academic_session_id`),
  KEY `admission_admitted_admitted_course_id_9f39ff41_fk_academics` (`admitted_course_id`),
  CONSTRAINT `admission_admitted_academic_session_id_d1579ad1_fk_academics` FOREIGN KEY (`academic_session_id`) REFERENCES `academics_academicsession` (`id`),
  CONSTRAINT `admission_admitted_admitted_course_id_9f39ff41_fk_academics` FOREIGN KEY (`admitted_course_id`) REFERENCES `academics_courseofstudy` (`id`),
  CONSTRAINT `admission_admitted_applicant_id_685e8d13_fk_auth_user_id` FOREIGN KEY (`applicant_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

