CREATE TABLE `admission_sponsordetails` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `full_name` varchar(70) DEFAULT NULL,
  `occupation` varchar(80) NOT NULL,
  `phone_number` varchar(11) DEFAULT NULL,
  `email` varchar(36) DEFAULT NULL,
  `home_address` varchar(120) DEFAULT NULL,
  `sponsor_relationship` varchar(100) NOT NULL,
  `added_date` datetime(6) NOT NULL,
  `applicant_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `applicant_id` (`applicant_id`),
  CONSTRAINT `admission_sponsordetails_applicant_id_d282f90e_fk_auth_user_id` FOREIGN KEY (`applicant_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
